const ACTION_NONE = '';
const ACTION_SET_PROTECT_LOSS = 'set_protect_loss';
const ACTION_SET_DYNAMIC_LOSS = 'set_dynamic_loss';

const TAKE_PROFIT_ACTION_OPTIONS = [
  { label: '不触发', value: ACTION_NONE },
  { label: '保本止损', value: ACTION_SET_PROTECT_LOSS },
  { label: '动态止损', value: ACTION_SET_DYNAMIC_LOSS },
];

const EXPIRATION_MODE_OPTIONS = [
  {
    label: '开市日',
    value: 'open_day',
    tooltip: '按开市日计数持有期（与 Investment 一致，常用）。',
  },
  {
    label: '交易日',
    value: 'trading_day',
    tooltip: '按交易日计数持有期。',
  },
  {
    label: '自然日',
    value: 'natural_day',
    tooltip: '按自然日计数持有期。',
  },
];

function takeProfitActionFromStage(stage) {
  const actions = Array.isArray(stage?.actions) ? stage.actions : [];
  if (actions.includes(ACTION_SET_DYNAMIC_LOSS)) return ACTION_SET_DYNAMIC_LOSS;
  if (actions.includes(ACTION_SET_PROTECT_LOSS)) return ACTION_SET_PROTECT_LOSS;
  return ACTION_NONE;
}

function takeProfitActionsFromAction(action) {
  return action ? [action] : [];
}

function toNumberOrEmpty(value, fallback = '') {
  if (value === '' || value === null || value === undefined) return fallback;
  const n = Number(value);
  return Number.isNaN(n) ? fallback : n;
}

function normalizeExpirationMode(expiration) {
  if (!expiration || typeof expiration !== 'object') return 'open_day';
  if (expiration.mode) return String(expiration.mode);
  return 'open_day';
}

/** settings 不写 name；运行期按 ratio 推断（-0.1→loss10%，0.1→win10%）。 */
function stripStageName(stage) {
  if (!stage || typeof stage !== 'object') return stage;
  const next = { ...stage };
  delete next.name;
  delete next._inferredName;
  return next;
}

/** 与 GoalSettings._to_stage_name 对齐（Python `{pct:g}`）。 */
function formatPctG(value) {
  if (!Number.isFinite(value)) return '';
  return String(Number(value.toPrecision(12)));
}

export function inferStageName(ratio, kind = 'stop_loss') {
  if (ratio === '' || ratio === null || ratio === undefined) return '';
  const n = Number(ratio);
  if (!Number.isFinite(n)) return '';
  const pct = formatPctG(Math.abs(n) * 100);
  if (kind === 'take_profit' || n > 0) return `win${pct}%`;
  if (n < 0) return `loss${pct}%`;
  return `level${pct}%`;
}

const EXPIRATION_MODE_SUMMARY = {
  trading_day: '交易日',
  natural_day: '自然日',
  open_day: '开盘日',
};

function stageCustomKey(stage) {
  return String(stage?.custom || '').trim();
}

function isCustomStage({ item } = {}) {
  return Boolean(stageCustomKey(item));
}

function collectStageActions(stage) {
  const seen = new Set();
  const out = [];
  const raw = Array.isArray(stage?.actions) ? stage.actions : [];
  raw.forEach((item) => {
    const key = String(item || '').trim();
    if (!key || seen.has(key)) return;
    seen.add(key);
    out.push(key);
  });
  const one = String(stage?.action || '').trim();
  if (one && !seen.has(one)) out.push(one);
  return out;
}

function formatRatioPct(ratio) {
  const n = Number(ratio);
  if (!Number.isFinite(n)) return '';
  return `${formatPctG(Math.abs(n) * 100)}%`;
}

function formatExitPhrase(spec) {
  if (!spec || typeof spec !== 'object') return '';
  if (spec.close_invest) return '清仓';
  const exitN = Number(spec.exit_ratio);
  if (Number.isFinite(exitN) && exitN >= 1) return '清仓';
  if (Number.isFinite(exitN) && exitN > 0) return `卖出 ${formatPctG(exitN * 100)}%`;
  return '';
}

function formatActionSuffix(stage) {
  const actions = collectStageActions(stage);
  const bits = [];
  if (actions.includes(ACTION_SET_PROTECT_LOSS)) bits.push('触发保护止损');
  if (actions.includes(ACTION_SET_DYNAMIC_LOSS)) bits.push('触发动态止损');
  return bits;
}

function formatStagePhrase(stage, kind) {
  if (stageCustomKey(stage)) {
    const desc = String(stage?.description || '').trim() || '未填写说明';
    return [`（自定义）${desc}`, ...formatActionSuffix(stage)].join(' ');
  }
  const pct = formatRatioPct(stage?.ratio);
  if (!pct) return '';
  const verb = kind === 'take_profit' ? '当盈利' : '当亏损';
  const parts = [`${verb} ${pct}`];
  const exit = formatExitPhrase(stage);
  if (exit) parts.push(exit);
  parts.push(...formatActionSuffix(stage));
  return parts.join(' ');
}

function hasActiveExpiration(goal) {
  if (!goal || typeof goal !== 'object') return false;
  if (goal.expirationEnabled === false) return false;
  const exp = goal.expiration;
  if (!exp || typeof exp !== 'object') return false;
  const days = Number(exp.fixed_window_in_days);
  return Number.isFinite(days) && days > 0;
}

function formatExpirationLine(goal) {
  if (!hasActiveExpiration(goal)) return '';
  const days = Number(goal.expiration.fixed_window_in_days);
  const daysText = Number.isInteger(days) ? String(days) : formatPctG(days);
  const mode = String(goal.expiration.mode || 'open_day').trim().toLowerCase();
  const label = EXPIRATION_MODE_SUMMARY[mode] || EXPIRATION_MODE_SUMMARY.open_day;
  return `最长持有：${daysText} 个${label}`;
}

function hasSideLoss(cfg) {
  if (!cfg || typeof cfg !== 'object') return false;
  if (cfg.ratio === '' || cfg.ratio == null) return false;
  return Number.isFinite(Number(cfg.ratio));
}

function formatProtectLossLine(cfg) {
  if (!hasSideLoss(cfg)) return '';
  const ratio = Number(cfg.ratio);
  const where = ratio === 0
    ? '买入成本'
    : `买入成本的 ${formatPctG((1 + ratio) * 100)}%`;
  const exit = formatExitPhrase(cfg) || '清仓';
  return `保护止损：当价格回落到${where} ${exit}`;
}

function formatDynamicLossLine(cfg) {
  if (!hasSideLoss(cfg)) return '';
  const pct = formatRatioPct(cfg.ratio);
  if (!pct) return '';
  const exit = formatExitPhrase(cfg) || '清仓';
  return `动态止损：当价格从最高回撤 ${pct} ${exit}`;
}

function formatSideStages(block, kind) {
  const stages = Array.isArray(block?.stages) ? block.stages : [];
  return stages
    .map((stage) => formatStagePhrase(stage, kind))
    .filter(Boolean)
    .join('；');
}

/** 顶栏「目标」栏：止盈 / 止损 / 持有期排成完整句子。 */
export function formatGoalSummaryLines(goal) {
  if (!goal || typeof goal !== 'object') return [];
  const lines = [];
  const expirationLine = formatExpirationLine(goal);
  if (expirationLine) lines.push(expirationLine);
  const takeProfit = formatSideStages(goal.take_profit, 'take_profit');
  if (takeProfit) lines.push(`止盈：${takeProfit}`);
  const stopLoss = formatSideStages(goal.stop_loss, 'stop_loss');
  if (stopLoss) lines.push(`止损：${stopLoss}`);
  const protect = formatProtectLossLine(goal.protect_loss);
  if (protect) lines.push(protect);
  const dynamic = formatDynamicLossLine(goal.dynamic_loss);
  if (dynamic) lines.push(dynamic);
  return lines;
}

function inferredNameField(kind) {
  return {
    key: '_inferredName',
    type: 'display',
    label: '阶段名称',
    tooltip: '由触发比例自动推断（settings 不写 name），不可编辑。',
    placeholder: ' ',
    visibleWhen: ({ item }) => !isCustomStage({ item }),
    resolve: ({ item }) => inferStageName(item?.ratio, kind),
  };
}

function customStageFields() {
  return [
    {
      key: 'custom',
      type: 'display',
      label: '自定义规则',
      tooltip: 'settings.py 里的 custom 钩子名，由 is_take_profit / is_stop_loss 判定。',
      placeholder: ' ',
      visibleWhen: isCustomStage,
      resolve: ({ item }) => stageCustomKey(item),
    },
    {
      key: 'description',
      type: 'text',
      label: '自定义说明',
      tooltip: '自定义目标必须填写，会显示在策略顶栏。',
      visibleWhen: isCustomStage,
    },
  ];
}

function normalizeStage(stage) {
  const exitRatio = stage?.exit_ratio;
  const custom = stageCustomKey(stage);
  return {
    ratio: custom ? '' : toNumberOrEmpty(stage?.ratio, ''),
    custom,
    description: String(stage?.description || '').trim(),
    close_invest: Boolean(stage?.close_invest),
    exit_ratio: toNumberOrEmpty(exitRatio, ''),
    actions: Array.isArray(stage?.actions) ? stage.actions : [],
    action: takeProfitActionFromStage(stage),
  };
}

function finalizeStageForSave(stage) {
  const next = stripStageName({ ...stage });
  delete next.action;
  const custom = stageCustomKey(next);
  const description = String(next.description || '').trim();
  if (custom) {
    next.custom = custom;
    delete next.ratio;
    if (description) next.description = description;
    else delete next.description;
  } else {
    delete next.custom;
    delete next.description;
  }
  return next;
}

function hasGoalExpiration(goal) {
  return goal?.expiration != null && typeof goal.expiration === 'object';
}

export function normalizeGoalSettings(goal) {
  const expirationEnabled = hasGoalExpiration(goal);
  return {
    expirationEnabled,
    expiration: expirationEnabled
      ? {
          fixed_window_in_days: toNumberOrEmpty(goal.expiration.fixed_window_in_days, ''),
          mode: normalizeExpirationMode(goal.expiration),
        }
      : {
          fixed_window_in_days: '',
          mode: 'open_day',
        },
    stop_loss: {
      stages: Array.isArray(goal?.stop_loss?.stages)
        ? goal.stop_loss.stages.map(normalizeStage)
        : [],
    },
    take_profit: {
      stages: Array.isArray(goal?.take_profit?.stages)
        ? goal.take_profit.stages.map(normalizeStage)
        : [],
    },
    protect_loss: goal?.protect_loss
      ? {
          ratio: toNumberOrEmpty(goal.protect_loss.ratio, 0),
          close_invest: true,
        }
      : undefined,
    dynamic_loss: goal?.dynamic_loss
      ? {
          ratio: toNumberOrEmpty(goal.dynamic_loss.ratio, -0.1),
          close_invest: Boolean(goal.dynamic_loss.close_invest),
        }
      : undefined,
  };
}

function stageHasTakeProfitAction(stage, actionName) {
  if (stage?.action === actionName) return true;
  const actions = Array.isArray(stage?.actions) ? stage.actions : [];
  return actions.includes(actionName);
}

function hasTakeProfitAction(goal, actionName) {
  const stages = goal?.take_profit?.stages || [];
  return stages.some((stage) => stageHasTakeProfitAction(stage, actionName));
}

const hasProtectLossAction = ({ values }) => hasTakeProfitAction(values, ACTION_SET_PROTECT_LOSS);
const hasDynamicLossAction = ({ values }) => hasTakeProfitAction(values, ACTION_SET_DYNAMIC_LOSS);

export function applyGoalActions(goal) {
  const next = { ...(goal || {}) };
  const expirationEnabled = Boolean(next.expirationEnabled);
  const expDraft = next.expiration && typeof next.expiration === 'object'
    ? next.expiration
    : {};

  delete next.expirationEnabled;

  if (expirationEnabled) {
    const days = toNumberOrEmpty(expDraft.fixed_window_in_days, 30);
    next.expiration = {
      fixed_window_in_days: days === '' ? 30 : days,
      mode: expDraft.mode || 'open_day',
    };
  } else {
    delete next.expiration;
  }

  const hasProtect = hasTakeProfitAction(next, ACTION_SET_PROTECT_LOSS);
  const hasDynamic = hasTakeProfitAction(next, ACTION_SET_DYNAMIC_LOSS);

  if (!hasProtect) {
    delete next.protect_loss;
  } else if (!next.protect_loss) {
    next.protect_loss = { ratio: 0, close_invest: true };
  } else {
    next.protect_loss = {
      ...next.protect_loss,
      close_invest: true,
    };
  }

  if (!hasDynamic) {
    delete next.dynamic_loss;
  } else if (!next.dynamic_loss) {
    next.dynamic_loss = { ratio: -0.1, close_invest: true };
  }

  if (next.take_profit?.stages) {
    next.take_profit = {
      ...next.take_profit,
      stages: next.take_profit.stages.map((stage) => {
        const { action, ...rest } = stage;
        return finalizeStageForSave({ ...rest, actions: takeProfitActionsFromAction(action) });
      }),
    };
  }

  if (next.stop_loss?.stages) {
    next.stop_loss = {
      ...next.stop_loss,
      stages: next.stop_loss.stages.map(({ action, ...rest }) => finalizeStageForSave(rest)),
    };
  }

  // 股票状态风控已迁至 simulation.risk_control
  delete next.stock_status_risk_management;

  return next;
}

